(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c7-advanced-2"]={"id":"unit22-trap-c7-advanced-2","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 정도","name":"심화 5지선다 2","level":"심화","desc":"2-2단원 · 정도","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"정도","parts":[{"name":"U22-34 · 불완전한 가격 지표와 가능한 대안","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 13문단]\n예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다. 그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다. 이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다. 오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다. 시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다. 어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-34-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["글쓴이는 표값만으로 누가 야구를 더 좋아하는지 완벽하게 알 수 있다고 본다.","누가 더 보고 싶어 하는지 판단할 때, 기다리려는 마음은 언제나 표값보다 정확한 기준이다.","기다리려는 모습으로는 경기를 보고 싶은 마음을 전혀 알 수 없다.","글쓴이는 표값만으로 누가 야구를 더 좋아하는지 알기 어렵다고 본다. 때로는 표를 받으려고 기꺼이 기다리는 모습이 더 좋은 판단 기준이다.","기다리려는 마음이 더 좋은 기준일 수 있다는 말은 시장을 지지하는 사람들만의 주장이다."],"answer":"글쓴이는 표값만으로 누가 야구를 더 좋아하는지 알기 어렵다고 본다. 때로는 표를 받으려고 기꺼이 기다리는 모습이 더 좋은 판단 기준이다.","why":"돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","choiceReviews":{"글쓴이는 표값만으로 누가 야구를 더 좋아하는지 알기 어렵다고 본다. 때로는 표를 받으려고 기꺼이 기다리는 모습이 더 좋은 판단 기준이다.":{"reason":"돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 표값만으로 누가 야구를 더 좋아하는지 완벽하게 알 수 있다고 본다.":{"reason":"바르게 고치면: 글쓴이는 표값만으로 누가 야구를 더 좋아하는지 완벽하게 알 수 없다고 본다.\n돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","edits":[{"start":35,"end":39,"before":"있다고 ","after":"없다고 "}]},"누가 더 보고 싶어 하는지 판단할 때, 기다리려는 마음은 언제나 표값보다 정확한 기준이다.":{"reason":"바르게 고치면: 누가 더 보고 싶어 하는지 판단할 때, 기다리려는 마음은 때로 표값보다 정확한 기준일 수 있다.\n돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","edits":[{"start":32,"end":36,"before":"언제나 ","after":"때로 "},{"start":45,"end":50,"before":"기준이다.","after":"기준일 수 있다."}]},"기다리려는 모습으로는 경기를 보고 싶은 마음을 전혀 알 수 없다.":{"reason":"바르게 고치면: 기다리려는 모습으로 경기를 보고 싶은 마음을 더 잘 알 수 있는 경우도 있다.\n돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","edits":[{"start":6,"end":12,"before":"모습으로는 ","after":"모습으로 "},{"start":26,"end":29,"before":"전혀 ","after":"더 잘 "},{"start":33,"end":36,"before":"없다.","after":"있는 경우도 있다."}]},"기다리려는 마음이 더 좋은 기준일 수 있다는 말은 시장을 지지하는 사람들만의 주장이다.":{"reason":"바르게 고치면: 기다리려는 마음이 더 좋은 기준일 수 있다는 말은 글쓴이의 주장이다.\n돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","edits":[{"start":28,"end":43,"before":"시장을 지지하는 사람들만의 ","after":"글쓴이의 "}]}},"pageSpecificReasons":true,"evidence":{"title":"불완전한 가격 지표와 가능한 대안","statement":"글쓴이는 표값만으로 누가 야구를 더 좋아하는지 알기 어렵다고 본다. 때로는 표를 받으려고 기꺼이 기다리는 모습이 더 좋은 판단 기준이다.","explanation":"돈을 많이 냈다고 언제나 더 열성적인 팬인 것은 아니에요. 어떤 때에는 줄을 서서 기다릴 만큼 보고 싶어 하는지가 관람하려는 마음을 더 잘 보여 줘요.\n13문단에서 확인할 수 있어요.","valid":["L13:5","L13:6"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.","paragraph":0,"memberIds":["L13:1"],"topic":"예를 들어 필자는 야구장에서 이런 사람들을 자주 본다. 늦게 와서 비싼 자리에 앉았다가 일찍 가 버리는 사람들이다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","paragraph":0,"memberIds":["L13:2"],"topic":"그럴 때 필자는 '저 사람들, 야구를 정말 좋아하는 걸까?' 하고 의심한다."},{"id":"L13:3","text":"이렇듯 비싼 관람석에 앉을 수 있는 경제적 능력은 경기를 향한 열정보다는 주머니 사정과 관계가 깊을 수 있다.","paragraph":0,"memberIds":["L13:3"],"topic":"이처럼 비싼 자리에 앉는 건 경기를 좋아하는 마음 때문이라기보다 돈이 많아서일 수 있다."},{"id":"L13:4","text":"오히려 경제적 여유는 없지만 선발 출전 선수들의 평균 타율을 전부 꿰고 있는 팬들, 특히 젊은 팬들이 그들보다 야구를 좋아하는 것만은 확실하다.","paragraph":0,"memberIds":["L13:4"],"topic":"오히려 돈은 없어도 선발 선수들의 타율(안타를 치는 비율)을 다 외우는 팬, 특히 젊은 팬들이 그 사람들보다 야구를 더 좋아하는 건 확실하다."},{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","paragraph":0,"memberIds":["L13:5"],"topic":"가격에는 마음과 돈(능력)이 같이 들어 있다. 그래서 가격만 보고는 누가 가장 좋아하는지 정확히 알 수 없다. 가격은 정확하지 않은 자(불완전한 지표)다."},{"id":"L13:6","text":"어떨 때는 공연을 관람하거나 야구 경기를 보기 위해 자발적으로 줄을 서고자 하는 태도가 가격을 지불하고자 하는 태도보다 관람을 정말 원하는 사람을 나타내는 지표일 수 있다.","paragraph":0,"memberIds":["L13:6"],"topic":"때로는 '몇 시간이라도 줄 서겠다'는 마음이 '돈을 내겠다'는 마음보다 진짜 팬을 더 잘 보여 줄 수 있다."}]}]},"editorSourceVersion":"51dea40196f8cea65dc647cf48b73c8621a8508f5915063e92a1bc776751c3ff"}]},{"name":"U22-37 · 경험적 문제라는 중간 결론","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 15문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 15문단]\n따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다. 그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다. 어떤 경우에든 시장이 이 역할을 더 잘 수행할지, 줄 서기가 더 잘 수행할지는 추상적인 경제적 논리에 따라 미리 결정할 수 없는 경험적 문제다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-37-S1","type":"mc","sent":"15문단의 내용과 맞는 설명은?","options":["돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 경제 이론만으로 미리 정할 수 있다.","돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 실제 사례를 살펴야 안다. 경제 이론만으로 미리 답을 정할 수는 없다.","어떻게 물건을 나눌지는 실제 사례를 보지 않고 이론만으로 판단하면 된다.","두 방법을 비교하는 목적은 가장 비싼 값을 내는 사람에게만 물건을 주는 것이다.","실제 사례를 자세히 살펴봐도 어느 방법으로 물건을 나누는 것이 나은지 판단할 수 없다."],"answer":"돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 실제 사례를 살펴야 안다. 경제 이론만으로 미리 답을 정할 수는 없다.","why":"두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","choiceReviews":{"돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 실제 사례를 살펴야 안다. 경제 이론만으로 미리 답을 정할 수는 없다.":{"reason":"두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","edits":[]},"돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 경제 이론만으로 미리 정할 수 있다.":{"reason":"바르게 고치면: 돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 경제 이론만으로 미리 정할 수 없다.\n두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","edits":[{"start":53,"end":56,"before":"있다.","after":"없다."}]},"어떻게 물건을 나눌지는 실제 사례를 보지 않고 이론만으로 판단하면 된다.":{"reason":"바르게 고치면: 어떻게 물건을 나눌지는 실제 사례를 살펴서 판단해야 한다.\n두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","edits":[{"start":20,"end":40,"before":"보지 않고 이론만으로 판단하면 된다.","after":"살펴서 판단해야 한다."}]},"두 방법을 비교하는 목적은 가장 비싼 값을 내는 사람에게만 물건을 주는 것이다.":{"reason":"바르게 고치면: 두 방법을 비교하는 목적은 물건을 가장 소중히 여기는 사람에게 주는 것이다.\n두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","edits":[{"start":11,"end":15,"before":"목적은 ","after":"목적은 물건을 "},{"start":18,"end":37,"before":"비싼 값을 내는 사람에게만 물건을 ","after":"소중히 여기는 사람에게 "}]},"실제 사례를 자세히 살펴봐도 어느 방법으로 물건을 나누는 것이 나은지 판단할 수 없다.":{"reason":"바르게 고치면: 실제 사례를 살펴서 어느 방법으로 물건을 나누는 것이 나은지 판단할 수 있다.\n두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","edits":[{"start":7,"end":16,"before":"자세히 살펴봐도 ","after":"살펴서 "},{"start":45,"end":48,"before":"없다.","after":"있다."}]}},"pageSpecificReasons":true,"evidence":{"title":"경험적 문제라는 중간 결론","statement":"돈을 받고 파는 방법과 줄을 세우는 방법 중 무엇이 더 나은지는 실제 사례를 살펴야 안다. 경제 이론만으로 미리 답을 정할 수는 없다.","explanation":"두 방법 중 어떤 방법이 물건을 더 소중히 여기는 사람에게 물건을 주는지 비교해야 해요. 글쓴이는 실제로 어떤 일이 일어나는지 살펴야 답을 찾을 수 있다고 봐요.\n15문단에서 확인할 수 있어요.","valid":["L15:1","L15:2","L15:3"],"sources":[{"id":"L15","title":"줄 서기를 돈으로 살 수 있을까","label":"15문단","sentences":[{"id":"L15:1","text":"따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다.","paragraph":0,"memberIds":["L15:1"],"topic":"그러니 \"시장이 줄 서기보다 낫다\"는 공리주의자의 말은 맞을 때도 있고 틀릴 때도 있다. 상황에 따라 그때그때 달라진다(우연에 크게 좌우된다)."},{"id":"L15:2","text":"그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다.","paragraph":0,"memberIds":["L15:2"],"topic":"가장 좋아하는 사람에게 물건을 잘 보내는 쪽이 어떤 때는 시장이고, 어떤 때는 줄 서기이기 때문이다."},{"id":"L15:3","text":"어떤 경우에든 시장이 이 역할을 더 잘 수행할지, 줄 서기가 더 잘 수행할지는 추상적인 경제적 논리에 따라 미리 결정할 수 없는 경험적 문제다.","paragraph":0,"memberIds":["L15:3"],"topic":"둘 중 뭐가 더 나은지는 머릿속 이론(추상적 논리)만으로 미리 정할 수 없다. 실제 상황을 보고 확인해야 안다(경험적 문제)."}]}]},"editorSourceVersion":"0d5a7beca7ac668e6d03d000d45d919e99f7b43172cf72d2e97890281268d9ce"}]},{"name":"U22-38 · 효용의 한계를 묻는 근본적 반박","items":[{"paragraphCount":1,"readingLabel":"16문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 16문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 16문단]\n그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다. 즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다. 어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다. 재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-38-S1","type":"mc","sent":"16문단의 내용과 맞는 설명은?","options":["글쓴이는 물건을 사고파는 사람이 얻는 이익만 중요하다고 본다.","'이익을 넘어선 가치'는 이익보다 못한 가치를 뜻한다.","글쓴이는 물건을 사고파는 사람이 얻는 이익 말고도 중요한 가치가 있다고 본다. 이익이 얼마나 늘어나는지만 보고 모든 물건을 판단할 수는 없다.","글쓴이는 모든 물건에 사고팔 때의 이익만으로 설명할 수 없는 가치가 있다고 단정한다.","물건을 사고팔 때의 이익 말고는 중요한 가치가 없다고 말한다."],"answer":"글쓴이는 물건을 사고파는 사람이 얻는 이익 말고도 중요한 가치가 있다고 본다. 이익이 얼마나 늘어나는지만 보고 모든 물건을 판단할 수는 없다.","why":"물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","choiceReviews":{"글쓴이는 물건을 사고파는 사람이 얻는 이익 말고도 중요한 가치가 있다고 본다. 이익이 얼마나 늘어나는지만 보고 모든 물건을 판단할 수는 없다.":{"reason":"물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","edits":[]},"글쓴이는 물건을 사고파는 사람이 얻는 이익만 중요하다고 본다.":{"reason":"바르게 고치면: 글쓴이는 물건을 사고파는 사람이 얻는 이익 말고도 중요한 가치가 있다고 본다.\n물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","edits":[{"start":21,"end":31,"before":"이익만 중요하다고 ","after":"이익 말고도 중요한 가치가 있다고 "}]},"'이익을 넘어선 가치'는 이익보다 못한 가치를 뜻한다.":{"reason":"바르게 고치면: '이익을 넘어선 가치'는 이익만으로 설명할 수 없는 가치를 뜻한다.\n물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","edits":[{"start":14,"end":22,"before":"이익보다 못한 ","after":"이익만으로 설명할 수 없는 "}]},"글쓴이는 모든 물건에 사고팔 때의 이익만으로 설명할 수 없는 가치가 있다고 단정한다.":{"reason":"바르게 고치면: 글쓴이는 어떤 물건에 사고팔 때의 이익만으로 설명할 수 없는 가치가 있을 수 있다고 말한다.\n물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","edits":[{"start":5,"end":8,"before":"모든 ","after":"어떤 "},{"start":34,"end":38,"before":"가치가 ","after":"가치가 있을 수 "},{"start":42,"end":47,"before":"단정한다.","after":"말한다."}]},"물건을 사고팔 때의 이익 말고는 중요한 가치가 없다고 말한다.":{"reason":"바르게 고치면: 물건을 사고팔 때의 이익 말고도 중요한 가치가 있다고 말한다.\n물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","edits":[{"start":14,"end":18,"before":"말고는 ","after":"말고도 "},{"start":26,"end":30,"before":"없다고 ","after":"있다고 "}]}},"pageSpecificReasons":true,"evidence":{"title":"효용의 한계를 묻는 근본적 반박","statement":"글쓴이는 물건을 사고파는 사람이 얻는 이익 말고도 중요한 가치가 있다고 본다. 이익이 얼마나 늘어나는지만 보고 모든 물건을 판단할 수는 없다.","explanation":"물건을 사거나 팔아서 얻는 만족과 이익이 가치의 전부는 아니에요. 어떤 물건에는 그런 이익만으로 설명할 수 없는 뜻과 가치도 있어요.\n16문단에서 확인할 수 있어요.","valid":["L16:2","L16:3"],"sources":[{"id":"L16","title":"줄 서기를 돈으로 살 수 있을까","label":"16문단","sentences":[{"id":"L16:1","text":"그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다.","paragraph":0,"memberIds":["L16:1"],"topic":"그런데 공리주의자의 주장에는 더 뿌리 깊은(근본적인) 문제가 있다."},{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.","paragraph":0,"memberIds":["L16:2"],"topic":"바로 '행복(효용)의 양만 따지는 생각이 전부는 아니다'라는 것이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.","paragraph":0,"memberIds":["L16:3"],"topic":"어떤 것은 사고파는 사람이 얻는 만족보다 더 큰 가치를 가진다."},{"id":"L16:4","text":"재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","paragraph":0,"memberIds":["L16:4"],"topic":"그리고 '어떻게 나눠 주느냐'가 그 물건의 진짜 의미(본질)의 일부일 수도 있다."}]}]},"editorSourceVersion":"993963c29edffab45044b74bce38760dbb7d03e8b15bd735d3e67d9ea35cbf2a"}]},{"name":"U22-39 · 분배 방식과 재화의 본질","items":[{"paragraphCount":1,"readingLabel":"16문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 16문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 16문단]\n그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다. 즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다. 어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다. 재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-39-S1","type":"mc","sent":"16문단의 내용과 맞는 설명은?","options":["물건을 나누어 주는 방법이 그 물건의 모든 의미를 반드시 결정한다.","물건을 나누어 주는 방법은 그 물건의 가치와 따로 생각해야 한다.","물건을 어떻게 나누어 주는지는 그 물건이 지닌 뜻과 언제나 상관없다.","물건을 누구에게 어떻게 나누어 주는지도 그 물건의 뜻과 가치를 이룰 수 있다. 그래서 물건의 가치를 생각할 때는 나누어 주는 방법도 살펴야 한다.","물건을 나누어 주는 방법이 달라져도 그 물건의 가치는 달라지지 않는다."],"answer":"물건을 누구에게 어떻게 나누어 주는지도 그 물건의 뜻과 가치를 이룰 수 있다. 그래서 물건의 가치를 생각할 때는 나누어 주는 방법도 살펴야 한다.","why":"물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","choiceReviews":{"물건을 누구에게 어떻게 나누어 주는지도 그 물건의 뜻과 가치를 이룰 수 있다. 그래서 물건의 가치를 생각할 때는 나누어 주는 방법도 살펴야 한다.":{"reason":"물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","edits":[]},"물건을 나누어 주는 방법이 그 물건의 모든 의미를 반드시 결정한다.":{"reason":"바르게 고치면: 물건을 나누어 주는 방법이 그 물건의 의미를 일부 이룰 수 있다.\n물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","edits":[{"start":21,"end":24,"before":"모든 ","after":""},{"start":28,"end":37,"before":"반드시 결정한다.","after":"일부 이룰 수 있다."}]},"물건을 나누어 주는 방법은 그 물건의 가치와 따로 생각해야 한다.":{"reason":"바르게 고치면: 물건을 나누어 주는 방법도 그 물건의 가치와 함께 생각해야 한다.\n물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","edits":[{"start":11,"end":15,"before":"방법은 ","after":"방법도 "},{"start":25,"end":28,"before":"따로 ","after":"함께 "}]},"물건을 어떻게 나누어 주는지는 그 물건이 지닌 뜻과 언제나 상관없다.":{"reason":"바르게 고치면: 물건을 어떻게 나누어 주는지는 그 물건이 지닌 뜻과 관련될 수 있다.\n물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","edits":[{"start":29,"end":38,"before":"언제나 상관없다.","after":"관련될 수 있다."}]},"물건을 나누어 주는 방법이 달라져도 그 물건의 가치는 달라지지 않는다.":{"reason":"바르게 고치면: 물건을 나누어 주는 방법이 달라지면 그 물건의 가치도 달라질 수 있다.\n물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","edits":[{"start":15,"end":20,"before":"달라져도 ","after":"달라지면 "},{"start":26,"end":39,"before":"가치는 달라지지 않는다.","after":"가치도 달라질 수 있다."}]}},"pageSpecificReasons":true,"evidence":{"title":"분배 방식과 재화의 본질","statement":"물건을 누구에게 어떻게 나누어 주는지도 그 물건의 뜻과 가치를 이룰 수 있다. 그래서 물건의 가치를 생각할 때는 나누어 주는 방법도 살펴야 한다.","explanation":"물건을 얻은 사람이 얼마나 만족하는지만 보는 것으로는 부족할 수 있어요. 그 물건을 누구에게 어떤 방법으로 주는지도 물건이 지닌 의미의 일부일 수 있기 때문이에요.\n16문단에서 확인할 수 있어요.","valid":["L16:4"],"sources":[{"id":"L16","title":"줄 서기를 돈으로 살 수 있을까","label":"16문단","sentences":[{"id":"L16:1","text":"그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다.","paragraph":0,"memberIds":["L16:1"],"topic":"그런데 공리주의자의 주장에는 더 뿌리 깊은(근본적인) 문제가 있다."},{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.","paragraph":0,"memberIds":["L16:2"],"topic":"바로 '행복(효용)의 양만 따지는 생각이 전부는 아니다'라는 것이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.","paragraph":0,"memberIds":["L16:3"],"topic":"어떤 것은 사고파는 사람이 얻는 만족보다 더 큰 가치를 가진다."},{"id":"L16:4","text":"재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","paragraph":0,"memberIds":["L16:4"],"topic":"그리고 '어떻게 나눠 주느냐'가 그 물건의 진짜 의미(본질)의 일부일 수도 있다."}]}]},"editorSourceVersion":"832d2eaa357d791d7efd35e6d1c0d8bd374e067b8793721d5d2855f933701cda"}]},{"name":"U22-41 · 시장 상품화로 사라지는 것","items":[{"paragraphCount":1,"readingLabel":"17문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 17문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 17문단]\n퍼블릭 시어터에서 주관하는 여름 셰익스피어 무료 공연에 관해 다시 한번 생각해 보자. 대변인은 대리 줄 서기에 반대하는 극장의 입장을 밝히면서 “우리는 사람들이 공연을 무료로 관람하기를 원한다.”라고 말했다. 하지만 그렇게 말한 이유는 무엇일까? 입장권이 사고팔린다고 해서 공연 관람이 어떻게 감소한다는 것일까? 물론 연극을 보고 싶지만 입장권을 구매할 경제적 여유가 없는 사람에게는 공연을 관람할 기회가 축소될 것이다. 하지만 문제는 공정성만이 아니다. 공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다. 그 상실의 결과는 가격 경쟁에서 밀린 사람들이 느끼는 실망만이 아니다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-41-S1","type":"mc","sent":"17문단의 내용과 맞는 설명은?","options":["무료 공연 표를 돈 받고 팔면 잃게 되는 가치가 있다. 돈이 없어 공연을 못 본 사람의 실망이 문제의 전부는 아니다.","무료 공연 표를 돈 받고 팔 때 생기는 문제는 표를 못 산 사람의 실망뿐이다.","무료 공연 표를 돈 받고 팔아도 잃게 되는 가치는 전혀 없다.","표를 살 돈이 없어도 공연을 볼 기회는 줄어들지 않는다.","돈 없는 사람도 공연을 보게 해 주면 따져 볼 다른 문제는 없다."],"answer":"무료 공연 표를 돈 받고 팔면 잃게 되는 가치가 있다. 돈이 없어 공연을 못 본 사람의 실망이 문제의 전부는 아니다.","why":"글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","choiceReviews":{"무료 공연 표를 돈 받고 팔면 잃게 되는 가치가 있다. 돈이 없어 공연을 못 본 사람의 실망이 문제의 전부는 아니다.":{"reason":"글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","edits":[]},"무료 공연 표를 돈 받고 팔 때 생기는 문제는 표를 못 산 사람의 실망뿐이다.":{"reason":"바르게 고치면: 무료 공연 표를 돈 받고 팔 때 생기는 문제는 표를 못 산 사람의 실망만이 아니다.\n글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","edits":[{"start":37,"end":43,"before":"실망뿐이다.","after":"실망만이 아니다."}]},"무료 공연 표를 돈 받고 팔아도 잃게 되는 가치는 전혀 없다.":{"reason":"바르게 고치면: 무료 공연 표를 돈 받고 팔면 잃게 되는 가치가 있다.\n글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","edits":[{"start":14,"end":18,"before":"팔아도 ","after":"팔면 "},{"start":24,"end":34,"before":"가치는 전혀 없다.","after":"가치가 있다."}]},"표를 살 돈이 없어도 공연을 볼 기회는 줄어들지 않는다.":{"reason":"바르게 고치면: 표를 살 돈이 없으면 공연을 볼 기회가 줄어든다.\n글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","edits":[{"start":8,"end":12,"before":"없어도 ","after":"없으면 "},{"start":18,"end":31,"before":"기회는 줄어들지 않는다.","after":"기회가 줄어든다."}]},"돈 없는 사람도 공연을 보게 해 주면 따져 볼 다른 문제는 없다.":{"reason":"바르게 고치면: 돈 없는 사람도 공연을 볼 수 있는지 외에 따져 볼 다른 문제도 있다.\n글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","edits":[{"start":13,"end":21,"before":"보게 해 주면 ","after":"볼 수 있는지 외에 "},{"start":29,"end":36,"before":"문제는 없다.","after":"문제도 있다."}]}},"pageSpecificReasons":true,"evidence":{"title":"시장 상품화로 사라지는 것","statement":"무료 공연 표를 돈 받고 팔면 잃게 되는 가치가 있다. 돈이 없어 공연을 못 본 사람의 실망이 문제의 전부는 아니다.","explanation":"글쓴이는 돈 없는 관객이 실망하는 문제를 무시하지 않아요. 다만 무료 공연을 돈 받고 파는 일에는 그보다 더 생각해 볼 문제가 있다고 봐요.\n17문단에서 확인할 수 있어요.","valid":["L17:6","L17:8"],"sources":[{"id":"L17","title":"줄 서기를 돈으로 살 수 있을까","label":"17문단","sentences":[{"id":"L17:1","text":"퍼블릭 시어터에서 주관하는 여름 셰익스피어 무료 공연에 관해 다시 한번 생각해 보자.","paragraph":0,"memberIds":["L17:1"],"topic":"처음의 무료 셰익스피어 공연으로 다시 돌아가 보자."},{"id":"L17:2","text":"대변인은 대리 줄 서기에 반대하는 극장의 입장을 밝히면서 “우리는 사람들이 공연을 무료로 관람하기를 원한다.”라고 말했다.","paragraph":0,"memberIds":["L17:2"],"topic":"대변인은 \"우리는 사람들이 공짜로 공연을 보기를 바란다.\"라고 했다."},{"id":"L17:3","text":"하지만 그렇게 말한 이유는 무엇일까?","paragraph":0,"memberIds":["L17:3"],"topic":"왜 그렇게 말했을까?"},{"id":"L17:4","text":"입장권이 사고팔린다고 해서 공연 관람이 어떻게 감소한다는 것일까?","paragraph":0,"memberIds":["L17:4"],"topic":"표를 사고판다고 해서 공연을 보는 일에서 뭐가 줄어든다는 걸까?"},{"id":"L17:5","text":"물론 연극을 보고 싶지만 입장권을 구매할 경제적 여유가 없는 사람에게는 공연을 관람할 기회가 축소될 것이다.","paragraph":0,"memberIds":["L17:5"],"topic":"물론 보고 싶지만 돈이 없는 사람은 공연을 볼 기회가 줄어든다."},{"id":"L17:6","text":"하지만 문제는 공정성만이 아니다.","paragraph":0,"memberIds":["L17:6"],"topic":"그런데 문제는 '불공평하다'는 것만이 아니다."},{"id":"L17:7","text":"공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다.","paragraph":0,"memberIds":["L17:7"],"topic":"모두를 위한 공짜 공연이 '사고파는 물건'이 되면 뭔가가 없어진다."},{"id":"L17:8","text":"그 상실의 결과는 가격 경쟁에서 밀린 사람들이 느끼는 실망만이 아니다.","paragraph":0,"memberIds":["L17:8"],"topic":"그 잃어버린 것은 돈 경쟁에서 진 사람들의 속상함만이 아니다."}]}]},"editorSourceVersion":"7e69db5db3bf818e3c9e9a60347a90062677027960bd55e53fc40a98272ed90c"}]},{"name":"U22-45 · 웹 적용 · 유니폼 경매","items":[{"paragraphCount":2,"readingLabel":"12문단 · 새 예시 적용","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.\n\n[새 적용 예시 · 원문 사례 아님]\n민준과 서진은 같은 팀 유니폼을 원한다. 민준은 가진 돈이 많아 높은 경매가를 제시했지만, 서진은 가진 돈이 적어 그 가격을 제시하지 못했다. 두 사람의 팬심 크기는 알려져 있지 않다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["정도"],"id":"U22-45-S1","type":"mc","sent":"12문단을 바탕으로 새 예시를 바르게 설명한 것은?","options":["더 비싼 값을 내겠다는 민준이 반드시 유니폼을 더 간절히 원한다.","서진은 유니폼을 소중히 여기지 않아서 높은 값을 내겠다고 하지 않았다.","경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음만 보여 준다.","돈이 더 적은 서진이 반드시 유니폼을 더 간절히 원한다.","민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다."],"answer":"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.","why":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","choiceReviews":{"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.":{"reason":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[]},"더 비싼 값을 내겠다는 민준이 반드시 유니폼을 더 간절히 원한다.":{"reason":"바르게 고치면: 더 비싼 값을 내겠다고 해서 민준이 유니폼을 더 간절히 원하는지는 알 수 없다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":8,"end":13,"before":"내겠다는 ","after":"내겠다고 해서 "},{"start":17,"end":21,"before":"반드시 ","after":""},{"start":32,"end":36,"before":"원한다.","after":"원하는지는 알 수 없다."}]},"서진은 유니폼을 소중히 여기지 않아서 높은 값을 내겠다고 하지 않았다.":{"reason":"바르게 고치면: 서진은 돈이 부족해서 높은 값을 내겠다고 하지 못했을 수도 있다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":4,"end":21,"before":"유니폼을 소중히 여기지 않아서 ","after":"돈이 부족해서 "},{"start":35,"end":39,"before":"않았다.","after":"못했을 수도 있다."}]},"경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음만 보여 준다.":{"reason":"바르게 고치면: 경매에서 얼마까지 내겠다는지는 돈을 내고 싶은 마음과 실제로 낼 수 있는 돈을 함께 보여 준다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":26,"end":30,"before":"마음만 ","after":"마음과 실제로 낼 수 있는 돈을 함께 "}]},"돈이 더 적은 서진이 반드시 유니폼을 더 간절히 원한다.":{"reason":"바르게 고치면: 돈이 더 적다고 해서 서진이 반드시 유니폼을 더 간절히 원하는 것은 아니다.\n돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","edits":[{"start":5,"end":8,"before":"적은 ","after":"적다고 해서 "},{"start":27,"end":31,"before":"원한다.","after":"원하는 것은 아니다."}]}},"pageSpecificReasons":true,"evidence":{"title":"웹 적용 · 유니폼 경매","statement":"민준이 더 비싼 값을 내겠다고 해서 서진보다 유니폼을 더 원하는지는 알 수 없다. 서진은 가진 돈이 부족해서 높은 값을 내지 못할 수도 있다.","explanation":"돈을 얼마까지 내겠다는지만 보면 유니폼을 얼마나 갖고 싶은지 정확히 알 수 없어요. 갖고 싶은 마음이 커도 가진 돈이 부족할 수 있기 때문이에요.\n유니폼 예시는 이해를 돕기 위해 만든 상황이에요. 12문단의 내용과 비교해 보세요.","valid":["L12:3","L12:4","L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"editorSourceVersion":"ee924affe8ff5c3c57113304cb8779fb787a1ac8902e589abdb6d11b9e7314a8"}]}]};})(window);
